/bin/zsh -lc "node -e '
const fs=require('\\''fs'\\''),p=require('\\''path'\\''),c=require('\\''crypto'\\'');
const need=(v,m)=>{if("'!v)throw Error(m)},fields=['"'\\''dev'\\'','\\''ino'\\'','\\''mode'\\'','\\''size'\\'','\\''mtimeNs'\\'','\\''ctimeNs'\\'','\\''nlink'\\''];
function readExact(i){const x=i.path;need(p.isAbsolute(x)&&p.normalize(x)===x,'\\''absolute normalized'\\'');let a='\\''/'\\'';for(const k of x.split('\\''/'\\'').filter(Boolean)){a=p.join(a,k);need("'!fs.lstatSync(a).isSymbolicLink(),'"'\\''symlink'\\'');}const s=fs.lstatSync(x,{bigint:true});need(s.isFile()&&s.size<=67108864n,'\\''regular cap'\\'');if(i.bytes"'!==undefined)need(s.size===BigInt(i.bytes),'"'\\''initial size'\\'');const same=t=>fields.every(k=>t[k]===s[k]);const fd=fs.openSync(x,fs.constants.O_RDONLY|fs.constants.O_NOFOLLOW);let b;try{need(same(fs.fstatSync(fd,{bigint:true})),'\\''fd-before'\\'');const chunks=[];let n=0,cap=Number(s.size)+1;while(n<cap){const z=Buffer.alloc(Math.min(65536,cap-n)),g=fs.readSync(fd,z,0,z.length,null);if("'!g)break;chunks.push(z.subarray(0,g));n+=g;}b=Buffer.concat(chunks);need(b.length===Number(s.size)&&same(fs.fstatSync(fd,{bigint:true})),'"'\\''fd-after/length'\\'');}finally{fs.closeSync(fd);}need(same(fs.lstatSync(x,{bigint:true}))&&fs.realpathSync(x)===x,'\\''path-after'\\'');const r={path:x,bytes:b.length,sha256:c.createHash('\\''sha256'\\'').update(b).digest('\\''hex'\\'')};if(i.sha256"'!==undefined)need(r.sha256===i.sha256,'"'\\''hash'\\'');return {...r,body:b};}
const simple=r=>({path:r.path,bytes:r.bytes,sha256:r.sha256});

const mode=process.argv[1]||'\\''final6'\\'';
need(mode==='\\''preseal'\\''||mode==='\\''final6'\\'','\\''mode'\\'');
const dir=\"/Volumes/AI_DATA/development/det-review-evidence/ri235-native-cross-root-d2-3vvw5uow\";
const four=[{\"path\":\"/Volumes/AI_DATA/development/det-review-evidence/ri235-native-cross-root-d2-3vvw5uow/CONNECTED_CONTRASTS.md\",\"bytes\":11022,\"sha256\":\"7e15a61e94d7d224a688987dfdc064098bda58e4861e2a34d24e75e433eb79ba\"},{\"path\":\"/Volumes/AI_DATA/development/det-review-evidence/ri235-native-cross-root-d2-3vvw5uow/D2_OBSTRUCTION.md\",\"bytes\":10510,\"sha256\":\"2af67ff423a5526e21beef2a66a6a02c8be6414df2afdc2d1afd315759d793f9\"},{\"path\":\"/Volumes/AI_DATA/development/det-review-evidence/ri235-native-cross-root-d2-3vvw5uow/HANDOFF.md\",\"bytes\":1807,\"sha256\":\"2a411e983a45df95ba1483e5a56d60d894e5b94a2f1827b1ab9fb57fd0cd88c4\"},{\"path\":\"/Volumes/AI_DATA/development/det-review-evidence/ri235-native-cross-root-d2-3vvw5uow/SOURCE_REFERENCES.json\",\"bytes\":79006,\"sha256\":\"9ba1af9217d7be73d598cd9fdce8e639b3819d708cc1e3a7e87d995c2b0bf97e\"}];
const expect4=['\\''CONNECTED_CONTRASTS.md'\\'','\\''D2_OBSTRUCTION.md'\\'','\\''HANDOFF.md'\\'','\\''SOURCE_REFERENCES.json'\\''].sort();
const expect6=[...expect4,'\\''AUTHOR_VERIFICATION.json'\\'','\\''HANDOFF.json'\\''].sort();
need(fs.lstatSync(dir).isDirectory()&&"'!fs.lstatSync(dir).isSymbolicLink(),'"'\\''reservation'\\'');
need(JSON.stringify(fs.readdirSync(dir).sort())===JSON.stringify(mode==='\\''preseal'\\''?expect4:expect6),'\\''namespace'\\'');
const reads=new Map();
function pinned(i){const r=readExact(i);const old=reads.get(r.path);if(old)need(old.bytes===r.bytes&&old.sha256===r.sha256,'\\''repeated identity'\\'');reads.set(r.path,simple(r));return r;}
const current=four.map(pinned);
const sr=current.find(r=>p.basename(r.path)==='\\''SOURCE_REFERENCES.json'\\'');
const S=JSON.parse(sr.body.toString('\\''utf8'\\''));
need(S.schema==='\\''ri235-admitted-source-references-v1'\\'','\\''reference schema'\\'');
need(S.status==='\\''SOURCE_ONLY_AUTHOR_PACKET_FOR_INDEPENDENT_REVIEW'\\'','\\''source status'\\'');
const ass=JSON.parse(pinned(S.assignment).body.toString('\\''utf8'\\''));
need(ass.schema==='\\''ri235-native-cross-root-assignment-v1'\\''&&ass.reservation===dir,'\\''assignment'\\'');
need(ass.owner_thread==='\\''01a074c4-4b09-76a3-8cb2-0caf116f6b9c'\\'','\\''owner'\\'');
const decision=JSON.parse(pinned(S.accepted_predecessor).body.toString('\\''utf8'\\''));
need(decision.status==='\\''ACCEPT_CONDITIONAL_ROOT_TRANSPORT_AND_EXACT_TWO_SECTOR_REDUCTION'\\'','\\''accepted predecessor'\\'');
const P=JSON.parse(pinned(S.predecessor_references).body.toString('\\''utf8'\\''));
need(S.preserved_boundary_keys.length===15,'\\''boundary count'\\'');
for(const k of S.preserved_boundary_keys)need(JSON.stringify(S.preserved_boundaries[k])===JSON.stringify(P[k]),'\\''preserved boundary '\\''+k);
const paths=S.direct_sources.map(x=>x.identity.path);
need(new Set(paths).size===paths.length,'\\''unique direct sources'\\'');
need(paths.length===51,'\\''direct source count'\\'');
for(const row of S.direct_sources){
need("'!row.identity.path.endsWith('"'\\''/CERTIFICATE.json'\\'')&&"'!row.identity.path.endsWith('"'\\''/check.py'\\''),'\\''no original scientific body or executable'\\'');
need(['\\''accepted-analytic-text'\\'','\\''administrative-reference'\\'','\\''opaque-historical-support'\\''].includes(row.access),'\\''access policy'\\'');
pinned(row.identity);
}
for(const row of P.direct_sources)need(S.direct_sources.some(x=>JSON.stringify(x.identity)===JSON.stringify(row.identity)),'\\''inherited direct identity preserved'\\'');
const scope=S.current_scope;
need(scope.manual_mathematical_reasoning===true,'\\''manual reasoning'\\'');
for(const k of ['\\''automatic_scientific_arithmetic'\\'','\\''scientific_body_read'\\'','\\''scientific_JSON_decoded'\\'','\\''new_coordinate_read'\\'','\\''original_RI41_exception_renewed'\\'','\\''new_amplitude'\\'','\\''H_or_z_reconstructed'\\'','\\''subject_execution'\\'','\\''measurement_access'\\'','\\''RET_access'\\'','\\''repository_changes'\\'','\\''git_or_index_operations'\\'','\\''successor_assigned'\\''])need(scope[k]===false,'\\''scope '\\''+k);
need(scope.qualification_credit===0,'\\''credit unchanged'\\'');
need(S.diagnostics.failed_shell_commands===1&&S.diagnostics.clipped_displays===2,'\\''diagnostics retained'\\'');
const previous=JSON.parse(pinned(S.predecessor_handoff).body.toString('\\''utf8'\\''));
need(previous.schema&&typeof previous.schema==='\\''string'\\'','\\''predecessor handoff metadata'\\'');
const previousNames=fs.readdirSync(p.dirname(S.predecessor_handoff.path)).sort();
need(JSON.stringify(previousNames)===JSON.stringify(['\\''AUTHOR_VERIFICATION.json'\\'','\\''HANDOFF.json'\\'','\\''HANDOFF.md'\\'','\\''OFFSET_ELIMINATION.md'\\'','\\''ROOT_TRANSPORT.md'\\'','\\''SOURCE_REFERENCES.json'\\''].sort()),'\\''predecessor six-file namespace'\\'');
let author=null,handoff=null;
if(mode==='\\''final6'\\''){
const hr=pinned({path:p.join(dir,'\\''HANDOFF.json'\\'')});
handoff=JSON.parse(hr.body.toString('\\''utf8'\\''));
need(handoff.schema==='\\''ri235-native-cross-root-d2-handoff-v1'\\'','\\''handoff schema'\\'');
need(handoff.status==='\\''SEALED_SOURCE_ONLY_AUTHOR_RESULT_PENDING_INDEPENDENT_REVIEW'\\'','\\''handoff status'\\'');
need(handoff.reservation===dir,'\\''handoff reservation'\\'');
need(handoff.files.length===5,'\\''five nonself payloads'\\'');
need(JSON.stringify(handoff.namespace)===JSON.stringify(expect6),'\\''handoff namespace'\\'');
for(const i of handoff.files)pinned(i);
const ai=handoff.files.find(i=>p.basename(i.path)==='\\''AUTHOR_VERIFICATION.json'\\'');need(ai,'\\''author pin'\\'');
author=JSON.parse(pinned(ai).body.toString('\\''utf8'\\''));
need(author.schema==='\\''ri235-author-verification-v1'\\'','\\''author schema'\\'');
need(author.independent_acceptance===false&&author.scientific_execution===false,'\\''author credit'\\'');
need(JSON.stringify(author.payloads)===JSON.stringify(four),'\\''author four pins'\\'');
need(JSON.stringify(author.diagnostics)===JSON.stringify(S.diagnostics),'\\''author diagnostics'\\'');
need(JSON.stringify(handoff.diagnostics)===JSON.stringify(S.diagnostics),'\\''handoff diagnostics'\\'');
need(handoff.full_normalized_witness===false&&handoff.actual_signed_inconsistency===false,'\\''open scientific result'\\'');
need(handoff.successor_assigned===false&&handoff.qualification_credit===0,'\\''handoff scope'\\'');
for(const i of four)need(handoff.files.some(x=>JSON.stringify(x)===JSON.stringify(i)),'\\''handoff four pins'\\'');
for(const filename of expect6)need(fs.lstatSync(p.join(dir,filename)).isFile(),'\\''local Markdown destination'\\'');
}
for(const i of reads.values())readExact(i);
console.log(JSON.stringify({
schema:'\\''ri235-metadata-check-result-v1'\\'',mode,exit_intent:0,
scope:'\\''Metadata identities, namespace, administrative declarations and unchanged boundaries only. No mathematical content parsing or scientific arithmetic.'\\'',
direct_sources:S.direct_sources.length,direct_bytes:S.direct_sources.reduce((n,x)=>n+x.identity.bytes,0),
whole_identities:reads.size,preserved_boundaries:S.preserved_boundary_keys.length,
predecessor_namespace:previousNames,current_namespace:mode==='\\''preseal'\\''?expect4:expect6,
inherited_manifest_by_reference:S.preserved_boundaries.inherited_manifest_by_reference,
scientific_body_read:false,scientific_execution:false,proof_arithmetic:false,
current_identities:[...reads.values()].filter(x=>p.dirname(x.path)===dir),
read_identities:[...reads.values()]
}));
' final6"
